import pandas as pd

def compute_signal(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy().sort_values(["permno", "time_avail_m"])
    df["prior_total_assets"] = df.groupby("permno", sort=False)["at"].shift(1)
    df["signal"] = (df["at"] - df["prior_total_assets"]) / df["prior_total_assets"]
    df = df[
        df["at"].notna()
        & df["prior_total_assets"].notna()
        & (df["at"] != 0)
        & (df["prior_total_assets"] != 0)
        & df["signal"].notna()
        & ~df["signal"].isin([float("inf"), float("-inf")])
    ]
    return df[["permno", "time_avail_m", "signal"]].rename(
        columns={"time_avail_m": "yyyymm"}
    )
